<script setup lang="ts">
import { computed, ref } from 'vue'
import { IconCheck, IconSparkles } from '@tabler/icons-vue'
import type { ProductCatalogItem, ProductMatch } from '@/api/contracts'

const props = defineProps<{ catalog: ProductCatalogItem[]; matches: ProductMatch[]; selectedProductId?: string; selectedProductIds: string[] }>()
const emit = defineEmits<{ select: [product: ProductCatalogItem]; toggle: [product: ProductCatalogItem] }>()
const hovered = ref<ProductCatalogItem | null>(null)
const categories = ['云 GIS 服务器', '边缘 GIS', '组件端 GIS', '桌面端 GIS', 'Web 端 GIS', '移动端 GIS']
const grouped = computed(() => categories.map(category => ({ category, products: props.catalog.filter(item => item.category === category) })))
const matchMap = computed(() => new Map(props.matches.map(item => [item.productId, item])))
const detail = computed(() => hovered.value || props.catalog.find(item => item.id === props.selectedProductId) || null)
const select = (product: ProductCatalogItem) => { hovered.value = product; emit('select', product); emit('toggle', product) }
</script>

<template>
  <div class="product-universe">
    <div class="universe-stage">
      <svg class="mesh" viewBox="0 0 1000 650" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="meshLine"><stop stop-color="#24ddff" stop-opacity="0"/><stop offset=".5" stop-color="#24ddff" stop-opacity=".42"/><stop offset="1" stop-color="#24ddff" stop-opacity="0"/></linearGradient></defs><path v-for="d in ['M500 325L185 130','M500 325L500 90','M500 325L815 130','M500 325L815 520','M500 325L500 565','M500 325L185 520']" :key="d" :d="d" stroke="url(#meshLine)" stroke-width="1" fill="none"/><circle cx="500" cy="325" r="104" fill="none" stroke="#1ccce9" stroke-opacity=".12" stroke-dasharray="5 8"/><circle cx="500" cy="325" r="145" fill="none" stroke="#168cff" stroke-opacity=".07"/></svg>
      <div class="universe-core"><span><IconSparkles :size="21"/></span><b>SuperMap GIS</b><small>2026 · 12.1</small><i>22 PRODUCTS</i></div>
      <section v-for="(group,index) in grouped" :key="group.category" :class="['product-cluster',`cluster-${index}`]">
        <header><span>{{ String(index + 1).padStart(2,'0') }}</span><b>{{ group.category }}</b><em>{{ group.products.length }}</em></header>
        <div><button v-for="product in group.products" :key="product.id" :class="['product-node',{matched:matchMap.has(product.id),recommended:matchMap.get(product.id)?.recommended,chosen:selectedProductIds.includes(product.id),focused:selectedProductId===product.id}]" @mouseenter="hovered=product" @mouseleave="hovered=null" @click="select(product)"><i/><span>{{ product.name.replace('SuperMap ','') }}</span><IconCheck v-if="selectedProductIds.includes(product.id)" :size="11"/></button></div>
      </section>
      <div class="legend"><span><i/>产品目录</span><span><i class="matched"/>需求命中</span><span><i class="recommended"/>Agent 推荐</span><span><i class="chosen"/>已加入组合</span></div>
    </div>
    <aside class="product-detail" :class="{empty:!detail}">
      <template v-if="detail"><div class="detail-title"><span>{{ detail.category }}</span><b>{{ detail.name }}</b></div><p>{{ detail.description }}</p><div class="capabilities"><em v-for="capability in detail.capabilities" :key="capability">{{ capability }}</em></div><strong v-if="matchMap.has(detail.id)">匹配度 {{ matchMap.get(detail.id)?.matchScore }}%</strong><small v-else>产品目录节点</small></template>
      <template v-else><span>PRODUCT INSPECTOR</span><b>悬停查看产品，点击加入方案组合</b></template>
    </aside>
  </div>
</template>

<style scoped>
