-cluster header em{font-style:normal;text-align:right}.product-cluster>div{display:flex;flex-wrap:wrap;gap:5px}.product-node{min-height:27px;max-width:100%;display:flex;align-items:center;gap:5px;padding:0 7px;border:1px solid rgba(67,126,160,.19);border-radius:5px;background:rgba(7,31,46,.56);color:#7890a2;font-size:8px;transition:.18s}.product-node:hover,.product-node.focused{border-color:rgba(49,185,232,.62);color:#dff7ff;transform:translateY(-1px);box-shadow:0 0 12px rgba(35,174,225,.12)}.product-node>i{width:5px;height:5px;border-radius:50%;background:#476577}.product-node.matched{color:#8eeaff;border-color:rgba(41,195,232,.3);background:rgba(16,127,174,.13)}.product-node.matched>i{background:var(--cyan);box-shadow:0 0 8px var(--cyan)}.product-node.recommended{color:#b9ffe5;border-color:rgba(43,229,159,.42);background:rgba(27,157,113,.13)}.product-node.recommended>i{background:var(--success);box-shadow:0 0 8px var(--success);animation:pulse 1.2s infinite alternate}.product-node.chosen{color:#fff5c3;border-color:rgba(255,202,73,.72);background:rgba(183,125,18,.2);box-shadow:inset 0 0 12px rgba(255,190,53,.08)}.product-node.chosen>i{background:#ffc94b;box-shadow:0 0 8px #ffc94b}.product-node.chosen svg{color:#ffc94b}.cluster-0{left:2%;top:4%}.cluster-1{left:35%;top:3%;width:30%}.cluster-2{right:2%;top:4%}.cluster-3{right:2%;bottom:5%}.cluster-4{left:35%;bottom:4%;width:30%}.cluster-5{left:2%;bottom:5%}.product-detail{min-height:86px;display:grid;grid-template-columns:175px minmax(180px,1fr) minmax(190px,auto) 70px;align-items:center;gap:13px;padding:11px 14px;border-top:1px solid rgba(43,186,226,.25);background:linear-gradient(90deg,rgba(7,28,43,.98),rgba(2,13,22,.98))}.product-detail.empty{grid-template-columns:auto 1fr;align-content:center}.detail-title{display:grid;gap:5px}.detail-title span,.product-detail.empty>span{color:var(--cyan);font-size:8px;letter-spacing:1px}.detail-title b,.product-detail.empty>b{font-size:11px}.product-detail p{margin:0;color:var(-